import { hostErrorCopy } from './host-error-copy.mjs'

// Request IDs identify commands; pairing credentials are generated by the Host.
let serial = 0
export function newRequestId() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  return `mobile-${Date.now().toString(36)}-${(++serial).toString(36)}-${Math.random().toString(36).slice(2, 12)}`
}

export class DraftLedger {
  drafts = new Map()
  pending = new Map()
  constructor(makeId = newRequestId, durable) {
    this.makeId = makeId
    this.durable = durable
    if (durable) {
      this.drafts = new Map(Object.entries(durable.value.drafts))
      this.pending = new Map(Object.entries(durable.value.pending))
    }
  }
  persist() {
    if (!this.durable) return
    this.durable.value.drafts = Object.fromEntries(this.drafts)
    this.durable.value.pending = Object.fromEntries(this.pending)
    this.durable.save()
  }
  get(key) {
    return this.drafts.get(key) ?? ''
  }
  set(key, text) {
    this.drafts.set(key, String(text).slice(0, 8000))
    this.persist()
  }
  prepare(key) {
    const draft = this.get(key)
    const text = draft.trim()
    if (!text) throw new Error('EMPTY_MESSAGE')
    const existing = this.pending.get(key)
    if (
      existing?.text === text &&
      this.durable?.value.queue[existing.requestId]?.status === 'blocked'
    )
      throw new Error(this.durable.value.queue[existing.requestId].errorCode || 'COMMAND_REJECTED')
    if (existing?.text === text) return existing
    if (this.durable && this.durable.list().length >= 256) throw new Error('OUTBOX_FULL')
    const command = {
      requestId: this.makeId(),
      text,
      draft,
      createdAt: Date.now(),
      expiresAt: Date.now() + 7 * 86400_000,
    }
    this.pending.set(key, command)
    if (this.durable) this.durable.value.queue[command.requestId] = { key, ...command }
    this.persist()
    return command
  }
  acknowledge(key, requestId) {
    if (this.durable) delete this.durable.value.queue[requestId]
    const command = this.pending.get(key)
    if (!command || command.requestId !== requestId) {
      this.persist()
      return
    }
    if (this.get(key) === command.draft) this.drafts.set(key, '')
    this.pending.delete(key)
    this.persist()
  }
  // Detach a request from sending without losing its text or changing a newer draft.
  returnToDraft(key, requestId) {
    const queued = this.durable?.value.queue[requestId]
    if (!queued) return
    if (this.get(key).trim() && this.get(key).trim() !== queued.text)
      throw new Error('DRAFT_CONFLICT')
    if (!this.get(key).trim()) this.drafts.set(key, queued.draft || queued.text)
    delete this.durable.value.queue[requestId]
    if (this.pending.get(key)?.requestId === requestId) this.pending.delete(key)
    this.persist()
  }
}

export function normalizeHistory(messages) {
  if (!Array.isArray(messages)) throw new Error('INVALID_HISTORY')
  const seen = new Set()
  return messages.flatMap((row) => {
    if (
      !row ||
      typeof row.id !== 'string' ||
      !['user', 'assistant'].includes(row.role) ||
      typeof row.text !== 'string' ||
      (row.role === 'assistant' && !row.text.trim()) ||
      seen.has(row.id)
    )
      return []
    seen.add(row.id)
    return [
      {
        id: row.id,
        role: row.role,
        text: row.text,
        at: typeof row.at === 'string' || typeof row.at === 'number' ? row.at : null,
      },
    ]
  })
}

export function normalizeHost(value) {
  const input = String(value).trim().replace(/\/$/, '')
  const match = /^(https?):\/\/([a-z0-9.-]+)(?::([0-9]{1,5}))?$/i.exec(input)
  if (!match || (match[3] && (+match[3] < 1 || +match[3] > 65535))) throw new Error('INVALID_HOST')
  const host = match[2].toLowerCase()
  if (match[1].toLowerCase() === 'http' && !['127.0.0.1', 'localhost', '10.0.2.2'].includes(host))
    throw new Error('HTTPS_REQUIRED')
  return `${match[1].toLowerCase()}://${host}${match[3] ? ':' + match[3] : ''}`
}

